import sys

MOD = 998244353


def mod(num):
    if num >= MOD:
        return num % MOD
    elif num < 0:
        return (num % MOD + MOD) % MOD
    return num


def mul(*args):
    if len(args) == 0:
        raise ValueError('args cannot be empty')
    if len(args) == 1:
        return args[0]
    a, b = args[0], args[1]
    if len(args) > 2:
        return mul(mul(a, b), *args[2:])
    return (a * b) % MOD


def getPrimes(n):
    nums = [1] * (n + 1)
    if n >= 0:
        nums[0] = 0
    if n >= 1:
        nums[1] = 0
    primes = []
    for i in range(2, n + 1):
        if nums[i]:
            primes.append(i)
        j = 0
        while j < len(primes) and primes[j] <= n // i:
            nums[primes[j] * i] = 0
            if i % primes[j] == 0:
                break
            j += 1
    return nums


def convertInput(read):
    def rn():
        return int(read())

    def rb():
        return int(read())

    def rns():
        return list(map(int, read().split()))

    def re_():
        return [int(s) - 1 for s in read().split()]

    def rbs():
        return list(map(int, read().split()))

    return rn, rb, rns, re_, rbs


def solve(read):
    rn, rb, rns, re_, rbs = convertInput(read)
    n, m = rns()
    pre = 1
    M = mod(m)
    res = 0
    ans = M
    ans1 = M
    p = getPrimes(n + 10)
    for i in range(2, n + 1):
        if pre <= m and p[i]:
            pre = pre * i
        if pre > m:
            ans = 0
        else:
            ans = mul(ans, m // pre)
        ans1 = mul(ans1, M)
        res = mod(res + ans1 - ans)
    return res


def main(r):
    try:
        t = 1
        res = [None] * t
        limit = 0
        for i in range(t):
            s = solve(r)
            if s is None:
                s = ''
            if t < limit:
                pass
            else:
                res[i] = s
        if t >= limit:
            return '\n'.join(str(x) for x in res)
    except Exception as error:
        print(error)


def read_input():
    import re
    data = sys.stdin.read()
    inputs = re.split(r'\r?\n', data)
    idx = [0]

    def read():
        val = inputs[idx[0]]
        idx[0] += 1
        return val

    return read


if __name__ == '__main__':
    read = read_input()
    output = main(read)
    sys.stdout.write(output)
